SELECT id, device_type, status, priority, dorm_building, dorm_room, create_time
FROM repair_order


        AND id = #{queryDTO.id}



        AND status = #{queryDTO.status}


        AND device_type = #{queryDTO.deviceType}


        AND REPLACE(dorm_building, ' ', '') LIKE CONCAT('%', REPLACE(#{queryDTO.dormBuilding}, ' ', ''), '%')


        AND create_time >= #{queryDTO.startTime}


        AND create_time < #{queryDTO.endTime}


    AND priority = #{queryDTO.priority}



    AND dorm_room = #{queryDTO.dormRoom}



ORDER BY create_time DESC

SELECT COUNT(*) FROM repair_order


        AND id = #{queryDTO.id}


        AND status = #{queryDTO.status}


        AND REPLACE(dorm_building, ' ', '') LIKE CONCAT('%', REPLACE(#{queryDTO.dormBuilding}, ' ', ''), '%')


